import{_ as r,l as s,o as e,c as o,v as t,p as l,x as i,d as B,i as E,S as d}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"国际风险分担","description":"","frontmatter":{"title":"国际风险分担","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/international-risk-sharing.md","filePath":"econ/international-risk-sharing.md","lastUpdated":1789023840000}'),c={name:"econ/international-risk-sharing.md"};function h(p,a,m,u,A,_){const n=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="国际风险分担" tabindex="-1">国际风险分担 <a class="header-anchor" href="#国际风险分担" aria-label="Permalink to &quot;国际风险分担&quot;">​</a></h1><div class="epigraph"><p>完全市场下国别消费应只跟全球冲击走，相对边际效用跟实际汇率锁在一起；数据里消费更本国、相关更低——分担远不完整。</p><footer>—— Backus, Kehoe and Kydland, International Real Business Cycles, JPE 1992；Obstfeld and Rogoff 风险分担；对照 Backus–Smith</footer></div><p><a href="/econ/forward-premium-puzzle">上一课</a>写价格侧 UIP 失败。本课换数量：消费是否已保险。主干<a href="/econ/backus-smith">Backus–Smith</a> 已把 \\(q\\) 与相对消费的锁写过；本课补完整分担的其他检验与 Obstfeld–Rogoff 的开放宏观，不重推那把锁。货币危机下一课换突然的价格与流量断裂。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>完全市场：各国 \\(m\\) 对齐到同一状态价格（允许 \\(q\\)）。于是国别消费增长应高度相关，特异冲击被资产市场吸收。BKK：观测是产出相关高于消费相关——与保险相反（保险应使消费相关高于产出）。Obstfeld：用资产持有与消费欧拉估分担程度，远小于 1。缺口不是再写原罪净值，而是：即便没有危机，日常分担也薄。主乡偏好、不可贸易、市场不完全是候选。</p><p><span class="marginnote">渠道：跨国持股、汇款、援助、借贷。数量上都不够把特异冲击抹平。Gourinchas–Rey 的估值效应是价格渠道的分担，危机时可以反向放大。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检验：消费增长对全球 vs 本国产出的回归；跨国消费相关；Backus–Smith 相关（已有课）。资产：本国股权持有比例（French–Poterba 主乡）。模型：不完全市场、贸易成本、不可贸易冲击可以把谜减小，难以同时打中脱节、FH、主乡。本课列机制，不选唯一。</p>',8)),(e(),l(d,null,{default:i(()=>[E(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CM%5B%22%E5%AE%8C%E5%85%A8%E5%B8%82%E5%9C%BA%22%5D%20--%3E%20INS%5B%22%E6%B6%88%E8%B4%B9%E7%9B%B8%E5%85%B3%20%3E%20%E4%BA%A7%E5%87%BA%E7%9B%B8%E5%85%B3%22%5D%0A%20%20DATA%5B%22%E4%BA%A7%E5%87%BA%E7%9B%B8%E5%85%B3%E6%9B%B4%E9%AB%98%22%5D%20--%3E%20FAIL%5B%22%E5%88%86%E6%8B%85%E4%B8%8D%E5%AE%8C%E6%95%B4%22%5D%0A%20%20HOME%5B%22%E4%B8%BB%E4%B9%A1%E6%8C%81%E8%82%A1%22%5D%20--%3E%20FAIL%0A%20%20NT%5B%22%E4%B8%8D%E5%8F%AF%E8%B4%B8%E6%98%93%20%2F%20%E8%B4%B8%E6%98%93%E6%88%90%E6%9C%AC%22%5D%20--%3E%20PART%5B%22%E9%83%A8%E5%88%86%E5%92%8C%E8%A7%A3%22%5D%0A%20%20BS%5B%22Backus%E2%80%93Smith%20q%20%E9%94%81%22%5D%20--%3E%20FAIL2%5B%22%E4%BB%B7%E6%A0%BC%E4%BE%A7%E4%B9%9F%E4%B8%8D%E9%94%81%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 Lucas 悖论：穷国不能用资产市场买保险，与资本不流入是同一不完全的两面。与全球失衡：买美债可以是买保险，上流是分担的一种（把风险卖给愿意生产安全资产的国家）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是状态价格未对齐。摩擦：主权、执行、信息、不可贸易。结果：各国更多靠国内储蓄平滑（FH 味道），靠 \\(q\\) 调整（但 Backus–Smith 说 \\(q\\) 也没按教科书调）。危机时本应是保险赔付日，资本却流出（突然停止）——保险符号反了，后课危机模型。</p><p>与 UIP 谜：价格错与数量错可以同源（\\(m\\) 的国别成分），不必。风险溢价可以很大而持股仍主乡（参与、分割）。</p><p><span class="marginnote">Aid 与汇款在发展中国家是重要渠道，但不进入 BKK 的 OECD 样本主叙事。分层：富国之间已经分担不足，穷国更不足。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重做 Backus–Smith 的公式。不把主乡写成非理性唯一解释——对冲人力资本、分散成本、信息都可以理性。下一课货币危机：不完全分担在坏状态下变成跑。不要用本课写组合基金的国际配置手册，也不进限价簿。</p><p>后课默认：完全市场的消费保险在数据上失败；主乡、不可贸易、市场不完全是菜单。Backus–Smith 是价格锁，BKK 是数量相关，两课一起用。危机模型下一课把失败写成跑与钉住崩溃。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>完全市场：消费应保险，相关应高于产出；数据相反。</li><li>主乡持股与薄的跨境保险工具。</li><li>Backus–Smith 的 \\(q\\) 锁是同一失败的价格面。</li><li>上流买安全资产可以是分担，危机时符号可反。</li><li>出处：Backus, Kehoe and Kydland, <em>JPE</em> 1992；Obstfeld；French and Poterba；Backus and Smith 1993。</li></ul>',10))])}const S=r(c,[["render",h]]);export{k as __pageData,S as default};
